def ev(f, env):
    if isinstance(f, str):
        return env[f]
    op = f[0]
    if op == "not":
        return not ev(f[1], env)
    a = ev(f[1], env)
    b = ev(f[2], env)
    if op == "and":
        return a and b
    if op == "or":
        return a or b
    return (not a) or b
def is_tautology(f, names):
    n = len(names)
    for i in range(2 ** n):
        env = {}
        for j in range(n):
            env[names[j]] = (i // (2 ** j)) % 2 == 1
        if not ev(f, env):
            return False
    return True

