def neg(l):
    if l[0] == "-":
        return l[1:]
    return "-" + l
def resolve(c1, c2):
    for l in c1:
        if neg(l) in c2:
            rest = {}
            for x in c1:
                if x != l:
                    rest[x] = 1
            for x in c2:
                if x != neg(l):
                    rest[x] = 1
            return sorted(rest.keys())
