practice.solution:
def is_var(t):
    return isinstance(t, str) and t[0].islower()
def walk(t, s):
    while is_var(t) and t in s:
        t = s[t]
    return t
def occurs(v, t, s):
    t = walk(t, s)
    if t == v:
        return True
    if isinstance(t, list):
        for x in t:
            if occurs(v, x, s):
                return True
    return False
def uni(a, b, s):
    a = walk(a, s)
    b = walk(b, s)
    if a == b:
        return s
    if is_var(a):
        if occurs(a, b, s):
            return None
        s[a] = b
        return s
    if is_var(b):
        if occurs(b, a, s):
            return None
        s[b] = a
        return s
    if isinstance(a, list) and isinstance(b, list) and len(a) == len(b):
        for i in range(len(a)):
            s = uni(a[i], b[i], s)
            if s is None:
                return None
        return s
    return None
def unify(a, b):
    s = uni(a, b, {})
    if s is None:
        return None
    out = []
    for k in sorted(s.keys()):
        out.append([k, s[k]])
    return out

