def bfs(graph, start, goal):
    queue = [[start]]
    seen = {start: 1}
    head = 0
    while head < len(queue):
        path = queue[head]
        head = head + 1
        node = path[len(path) - 1]
        if node == goal:
            return path
        for nb in graph.get(node, []):
            if nb not in seen:
                seen[nb] = 1
                queue.append(path + [nb])
    return []

