def ab_count(tree, maximizing):
    count = [0]
    def go(t, mx, alpha, beta):
        if not isinstance(t, list):
            count[0] = count[0] + 1
            return t
        if mx:
            v = -1000
            for c in t:
                v = max(v, go(c, False, alpha, beta))
                alpha = max(alpha, v)
                if beta <= alpha:
                    break
            return v
        v = 1000
        for c in t:
            v = min(v, go(c, True, alpha, beta))
            beta = min(beta, v)
            if beta <= alpha:
                break
        return v
    value = go(tree, maximizing, -1000, 1000)
    return [value, count[0]]

