def plan(init, goal, actions):
    start = sorted(init)
    queue = [[start, []]]
    seen = {tuple(start): 1}
    head = 0
    while head < len(queue):
        state, steps = queue[head]
        head = head + 1
        ok = True
        for g in goal:
            if g not in state:
                ok = False
        if ok:
            return steps
        for a in actions:
            good = True
            for p in a["pre"]:
                if p not in state:
                    good = False
            if not good:
                continue
            new = {}
            for f in state:
                if f not in a["del"]:
                    new[f] = 1
            for f in a["add"]:
                new[f] = 1
            ns = sorted(new.keys())
            key = tuple(ns)
            if key not in seen:
                seen[key] = 1
                queue.append([ns, steps + [a["name"]]])
    return None

