practice.solution:
def colour_map(graph, colours):
    regions = sorted(graph.keys())
    assign = {}
    def ok(r, c):
        for nb in graph[r]:
            if assign.get(nb) == c:
                return False
        return True
    def go(i):
        if i == len(regions):
            return True
        r = regions[i]
        for c in colours:
            if ok(r, c):
                assign[r] = c
                if go(i + 1):
                    return True
                del assign[r]
        return False
    if go(0):
        return [assign[r] for r in regions]
    return None

