practice.solution:
def queens(n):
    cols = []
    def ok(c):
        r = len(cols)
        for i in range(r):
            if cols[i] == c or abs(cols[i] - c) == r - i:
                return False
        return True
    def go():
        if len(cols) == n:
            return 1
        total = 0
        for c in range(n):
            if ok(c):
                cols.append(c)
                total = total + go()
                cols.pop()
        return total
    return go()

